From 0a6fde6b3098d7c9959029b6b0ef43037ef9998c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:37:00 +0100
Subject: [PATCH] applets/taskmanager: Highlight the window over its whole
 tooltip entry

With thumbnails on, the window was only highlighted while hovering its
thumbnail, so moving to the title, close button or media controls
brought the other windows back. Track hover on the whole entry instead.

BUG: 528348
---
 applets/taskmanager/qml/ToolTipInstance.qml | 19 +++++++++++--------
 1 file changed, 11 insertions(+), 8 deletions(-)

diff --git a/applets/taskmanager/qml/ToolTipInstance.qml b/applets/taskmanager/qml/ToolTipInstance.qml
index 5a42d24a17..1e911479ab 100644
--- a/applets/taskmanager/qml/ToolTipInstance.qml
+++ b/applets/taskmanager/qml/ToolTipInstance.qml
@@ -78,6 +78,15 @@ ColumnLayout {
     // Lots of spacing with no thumbnails looks bad
     spacing: Plasmoid.configuration.showToolTips ? Kirigami.Units.smallSpacing : 0

+    // Highlight the window anywhere in its entry. In a group, the player controls may belong to
+    // another window unless this one's title has the track, so they don't count there.
+    HoverHandler {
+        enabled: root.index !== -1 && thumbnailSourceItem.winId != undefined
+        readonly property bool highlight: hovered && (!toolTipDelegate.isGroup || root.titleIncludesTrack
+            || point.position.y < (playerController.visible ? playerController.y : volumeControls.visible ? volumeControls.y : root.height))
+        onHighlightChanged: tasks.windowsHovered([String(thumbnailSourceItem.winId)], highlight)
+    }
+
     // text labels + close button
     Item {
         id: headerItem
@@ -234,12 +243,6 @@ ColumnLayout {
             }
         }

-        component ToolTipHoverHandler: HoverHandler {
-            onHoveredChanged: {
-                tasks.windowsHovered([String(thumbnailSourceItem.winId)], hovered);
-            }
-        }
-
         component ToolTipTapHandler: TapHandler {
             acceptedButtons: Qt.LeftButton | Qt.RightButton | Qt.MiddleButton
             onTapped: (event, button) => {
@@ -260,7 +263,7 @@ ColumnLayout {
             }
         }

-        ToolTipHoverHandler {
+        HoverHandler {
             id: headerHoverHandler
             enabled: (root.index !== -1) && !Plasmoid.configuration.showToolTips && thumbnailSourceItem.winId != undefined
         }
@@ -386,7 +389,7 @@ ColumnLayout {
             visible: available
         }

-        ToolTipHoverHandler {
+        HoverHandler {
             id: hoverHandler
             enabled: root.index !== -1 && Plasmoid.configuration.showToolTips && thumbnailSourceItem.winId != undefined
         }
-- 
